import numpy as np
from scipy import stats

MAX_DRIVERS = 4

def design(feats):
    # Remove near-duplicates based on correlation
    ids = list(feats.ids)
    x = feats.x
    y = feats.y

    # Identify near-duplicates (correlation >= 0.6)
    corr_matrix = np.corrcoef(x.T)
    to_remove = set()
    for i in range(len(ids)):
        for j in range(i+1, len(ids)):
            if abs(corr_matrix[i,j]) >= 0.6:
                to_remove.add(ids[j])

    # Filter out near-duplicates
    keep_mask = [i for i in range(len(ids)) if ids[i] not in to_remove]
    keep_ids = [ids[i] for i in keep_mask]
    keep_x = x[:, keep_mask]

    # Calculate effect sizes using Welch's t-test
    effect_sizes = []
    for i, fid in enumerate(keep_ids):
        group0 = keep_x[y==0, i]
        group1 = keep_x[y==1, i]
        if len(group0) > 0 and len(group1) > 0:
            t_stat, _ = stats.ttest_ind(group0, group1, equal_var=False)
            effect_sizes.append((abs(t_stat), fid))
        else:
            effect_sizes.append((0, fid))

    # Sort by effect size and take top MAX_DRIVERS
    effect_sizes.sort(reverse=True)
    drivers = [fid for _, fid in effect_sizes[:MAX_DRIVERS]]

    # If no strong effects, return empty design
    if not drivers:
        return Design(drivers=(), columns=(), products=(), loadings={})

    # Build columns (include drivers and their correlates)
    columns = []
    for fid in keep_ids:
        if fid in drivers:
            columns.append(fid)
        else:
            # Include correlates of drivers (correlation >= 0.5)
            for drv in drivers:
                drv_idx = keep_ids.index(drv)
                fid_idx = keep_ids.index(fid)
                corr = abs(corr_matrix[drv_idx, fid_idx])
                if corr >= 0.5:
                    columns.append(fid)
                    break

    # Remove duplicates from columns while preserving order
    seen = set()
    unique_columns = []
    for fid in columns:
        if fid not in seen:
            seen.add(fid)
            unique_columns.append(fid)
    columns = unique_columns

    # Create products between drivers
    products = []
    for i, d1 in enumerate(drivers):
        for d2 in drivers[i+1:]:
            products.append((d1, d2))

    # Create weighted loading (simple sum of drivers)
    loadings = {fid: 1.0 for fid in drivers}

    return Design(drivers=tuple(drivers), columns=tuple(columns), products=tuple(products), loadings=loadings)
